      "order_index": 1,
      "title_bn": "পাঠ ১: আত্মকর্মসংস্থানের ধারণা ও গুরুত্ব",
      "content_text": "## ১. আত্মকর্মসংস্থান কী? (Concept of Self-Employment)\n\nনিজের পুঁজি বা ঋণ করা স্বল্প সম্পদ, নিজস্ব জ্ঞান, বুদ্ধি ও দক্ষতাকে কাজে লাগিয়ে জীবিকা অর্জনের জন্য যে নিজস্ব কর্মসংস্থান সৃষ্টি করা হয়, তাকে **আত্মকর্মসংস্থান (Self-employment)** বলে।\n\n> **সহজ কথায়:** \"নিজের উদ্যোগে নিজের কাজের ব্যবস্থা করা এবং নিজে নিজের কর্মসংস্থান গড়ে তোলার নামই আত্মকর্মসংস্থান।\"\n\nউদাহরণস্বরূপ:\n- দর্জির কাজ করে নিজের ট্রেইলারিং শপ পরিচালনা করা।\n- মৌমাছি পালন করে মধু উৎপাদন ও বাজারজাত করা।\n- নার্সারি বা মাশরুম চাষ করে জীবিকা নির্বাহ করা।\n- মোবাইল ফোন ও কম্পিউটার মেরামত সেবা দেওয়া।\n\n---\n\n## ২. কর্মসংস্থানের প্রকারভেদ\n\nকর্মসংস্থানকে প্রধানত তিন ভাগে ভাগ করা যায়:\n1. **মজুরি বা বেতনভিত্তিক চাকরি (Wage Employment / Job):** অন্যের অধীনে নির্দিষ্ট মাসিক বেতন বা দৈনিক মজুরির বিনিময়ে চুক্তি অনুযায়ী কাজ করা।\n2. **আত্মকর্মসংস্থান (Self-employment):** নিজের জ্ঞান ও শ্রমে স্বাধীনভাবে নিজস্ব উপার্জনের ব্যবস্থা করা।\n3. **ব্যবসায় উদ্যোগ (Business Entrepreneurship):** বৃহত্তর পরিসরে পুঁজি ও ঝুঁকি নিয়ে অন্যের জন্যও কর্মসংস্থান সৃষ্টি করা।\n\n---\n\n## ৩. আত্মকর্মসংস্থানের গুরুত্ব\n\n1. **স্বাধীন পেশা:** এতে কারো অধীনে থাকতে হয় না, ব্যক্তি নিজেই নিজের কাজের মনিব।\n2. **স্বল্প পুঁজি প্রয়োজন:** অল্প মূলধন নিয়েই ছোট পরিসরে ঘরে বসেই এ কাজ শুরু করা যায়।\n3. **অলস সময় দূরীকরণ:** যুব সমাজকে হতাশা, মাদক ও অপরাধপ্রবণতা থেকে মুক্ত রেখে উৎপাদনশীল কাজে যুক্ত করে।\n4. **নারীদের ক্ষমতায়ন:** কুটির শিল্প, বুটিক, হস্তশিল্প ও পোলট্রি খামারের মাধ্যমে গ্রাম ও শহরের নারীরা ঘরে বসেই স্বাবলম্বী হচ্ছে।",
      "content": "## ১. আত্মকর্মসংস্থান কী? (Concept of Self-Employment)\n\nনিজের পুঁজি বা ঋণ করা স্বল্প সম্পদ, নিজস্ব জ্ঞান, বুদ্ধি ও দক্ষতাকে কাজে লাগিয়ে জীবিকা অর্জনের জন্য যে নিজস্ব কর্মসংস্থান সৃষ্টি করা হয়, তাকে **আত্মকর্মসংস্থান (Self-employment)** বলে।\n\n> **সহজ কথায়:** \"নিজের উদ্যোগে নিজের কাজের ব্যবস্থা করা এবং নিজে নিজের কর্মসংস্থান গড়ে তোলার নামই আত্মকর্মসংস্থান।\"\n\nউদাহরণস্বরূপ:\n- দর্জির কাজ করে নিজের ট্রেইলারিং শপ পরিচালনা করা।\n- মৌমাছি পালন করে মধু উৎপাদন ও বাজারজাত করা।\n- নার্সারি বা মাশরুম চাষ করে জীবিকা নির্বাহ করা।\n- মোবাইল ফোন ও কম্পিউটার মেরামত সেবা দেওয়া।\n\n---\n\n## ২. কর্মসংস্থানের প্রকারভেদ\n\nকর্মসংস্থানকে প্রধানত তিন ভাগে ভাগ করা যায়:\n1. **মজুরি বা বেতনভিত্তিক চাকরি (Wage Employment / Job):** অন্যের অধীনে নির্দিষ্ট মাসিক বেতন বা দৈনিক মজুরির বিনিময়ে চুক্তি অনুযায়ী কাজ করা।\n2. **আত্মকর্মসংস্থান (Self-employment):** নিজের জ্ঞান ও শ্রমে স্বাধীনভাবে নিজস্ব উপার্জনের ব্যবস্থা করা।\n3. **ব্যবসায় উদ্যোগ (Business Entrepreneurship):** বৃহত্তর পরিসরে পুঁজি ও ঝুঁকি নিয়ে অন্যের জন্যও কর্মসংস্থান সৃষ্টি করা।\n\n---\n\n## ৩. আত্মকর্মসংস্থানের গুরুত্ব\n\n1. **স্বাধীন পেশা:** এতে কারো অধীনে থাকতে হয় না, ব্যক্তি নিজেই নিজের কাজের মনিব।\n2. **স্বল্প পুঁজি প্রয়োজন:** অল্প মূলধন নিয়েই ছোট পরিসরে ঘরে বসেই এ কাজ শুরু করা যায়।\n3. **অলস সময় দূরীকরণ:** যুব সমাজকে হতাশা, মাদক ও অপরাধপ্রবণতা থেকে মুক্ত রেখে উৎপাদনশীল কাজে যুক্ত করে।\n4. **নারীদের ক্ষমতায়ন:** কুটির শিল্প, বুটিক, হস্তশিল্প ও পোলট্রি খামারের মাধ্যমে গ্রাম ও শহরের নারীরা ঘরে বসেই স্বাবলম্বী হচ্ছে।"
