      "order_index": 2,
      "title_bn": "পাঠ ২: যৌথ মূলধনী কোম্পানি (Company Organization)",
      "content_text": "## ১. যৌথ মূলধনী কোম্পানির ধারণা\n\nকোম্পানি আইন (বাংলাদেশে ১৯৯৪ সালের কোম্পানি আইন) অনুযায়ী গঠিত ও নিবন্ধিত, কৃত্রিম ব্যক্তিসত্তা ও চিরন্তন অস্তিত্বসম্পন্ন এবং শেয়ারের দ্বারা সীমাবদ্ধ দায়বিশিষ্ট ব্যবসায় সংগঠনকে **যৌথ মূলধনী কোম্পানি (Joint Stock Company)** বলে।\n\n### প্রধান বৈশিষ্ট্যসমূহ:\n1. **আইনসৃষ্ট প্রতিষ্ঠান:** ১৯৯৪ সালের কোম্পানি আইন দ্বারা বিধিবদ্ধভাবে গঠিত ও বিলুপ্ত হয়।\n2. **কৃত্রিম ব্যক্তিসত্তা (Artificial Personality):** মানুষের মতো রক্ত-মাংসের দেহ না থাকলেও কোম্পানি নিজের নামে সম্পত্তি ক্রয়, চুক্তি সম্পাদন এবং আদালতে মামলা করতে পারে।\n3. **কমন সিলমোহর (Common Seal):** কোম্পানির আনুষ্ঠানিক স্বাক্ষরের প্রতীক হিসেবে নির্দিষ্ট সিলমোহর ব্যবহৃত হয়।\n4. **চিরন্তন অস্তিত্ব (Perpetual Succession):** কোনো শেয়ারহোল্ডারের মৃত্যু বা দেউলিয়া হওয়ার কারণে কোম্পানির অস্তিত্ব বিলুপ্ত হয় না।\n5. **সীমাবদ্ধ দায় (Limited Liability):** শেয়ারহোল্ডারদের দায় তাঁদের ক্রয়কৃত শেয়ারের আঙ্কিক মূল্যের মধ্যে সীমাবদ্ধ থাকে।\n\n---\n\n## ২. প্রাইভেট ও পাবলিক লিমিটেড কোম্পানির তুলনা\n\n| তুলনার বিষয় | প্রাইভেট লিমিটেড কোম্পানি | পাবলিক লিমিটেড কোম্পানি |\n| :--- | :--- | :--- |\n| **সদস্য সংখ্যা** | সর্বনিম্ন ২ জন, সর্বোচ্চ ৫০ জন | সর্বনিম্ন ৭ জন, সর্বোচ্চ শেয়ার সংখ্যা দ্বারা সীমাবদ্ধ |\n| **পরিচালক সংখ্যা** | ন্যূনতম ২ জন পরিচালক | ন্যূনতম ৩ জন পরিচালক |\n| **জনগণের নিকট শেয়ার বিক্রয়** | পারে না (শেয়ার হস্তান্তর নিষিদ্ধ) | শেয়ার ও ঋণপত্র বিক্রির জন্য জনগণের নিকট বিবরণপত্র ছাড়ে |\n| **শেয়ার হস্তান্তরযোগ্যতা** | অবাধে হস্তান্তরযোগ্য নয় | শেয়ার বাজারে অবাধে কেনাবেচা ও হস্তান্তর করা যায় |\n| **কার্য আরম্ভ** | নিবন্ধনপত্র পেলেই ব্যবসা শুরু করতে পারে | নিবন্ধনপত্র এবং কার্যারম্ভের অনুমতিপত্র উভয়ই প্রয়োজন |",
      "content": "## ১. যৌথ মূলধনী কোম্পানির ধারণা\n\nকোম্পানি আইন (বাংলাদেশে ১৯৯৪ সালের কোম্পানি আইন) অনুযায়ী গঠিত ও নিবন্ধিত, কৃত্রিম ব্যক্তিসত্তা ও চিরন্তন অস্তিত্বসম্পন্ন এবং শেয়ারের দ্বারা সীমাবদ্ধ দায়বিশিষ্ট ব্যবসায় সংগঠনকে **যৌথ মূলধনী কোম্পানি (Joint Stock Company)** বলে।\n\n### প্রধান বৈশিষ্ট্যসমূহ:\n1. **আইনসৃষ্ট প্রতিষ্ঠান:** ১৯৯৪ সালের কোম্পানি আইন দ্বারা বিধিবদ্ধভাবে গঠিত ও বিলুপ্ত হয়।\n2. **কৃত্রিম ব্যক্তিসত্তা (Artificial Personality):** মানুষের মতো রক্ত-মাংসের দেহ না থাকলেও কোম্পানি নিজের নামে সম্পত্তি ক্রয়, চুক্তি সম্পাদন এবং আদালতে মামলা করতে পারে।\n3. **কমন সিলমোহর (Common Seal):** কোম্পানির আনুষ্ঠানিক স্বাক্ষরের প্রতীক হিসেবে নির্দিষ্ট সিলমোহর ব্যবহৃত হয়।\n4. **চিরন্তন অস্তিত্ব (Perpetual Succession):** কোনো শেয়ারহোল্ডারের মৃত্যু বা দেউলিয়া হওয়ার কারণে কোম্পানির অস্তিত্ব বিলুপ্ত হয় না।\n5. **সীমাবদ্ধ দায় (Limited Liability):** শেয়ারহোল্ডারদের দায় তাঁদের ক্রয়কৃত শেয়ারের আঙ্কিক মূল্যের মধ্যে সীমাবদ্ধ থাকে।\n\n---\n\n## ২. প্রাইভেট ও পাবলিক লিমিটেড কোম্পানির তুলনা\n\n| তুলনার বিষয় | প্রাইভেট লিমিটেড কোম্পানি | পাবলিক লিমিটেড কোম্পানি |\n| :--- | :--- | :--- |\n| **সদস্য সংখ্যা** | সর্বনিম্ন ২ জন, সর্বোচ্চ ৫০ জন | সর্বনিম্ন ৭ জন, সর্বোচ্চ শেয়ার সংখ্যা দ্বারা সীমাবদ্ধ |\n| **পরিচালক সংখ্যা** | ন্যূনতম ২ জন পরিচালক | ন্যূনতম ৩ জন পরিচালক |\n| **জনগণের নিকট শেয়ার বিক্রয়** | পারে না (শেয়ার হস্তান্তর নিষিদ্ধ) | শেয়ার ও ঋণপত্র বিক্রির জন্য জনগণের নিকট বিবরণপত্র ছাড়ে |\n| **শেয়ার হস্তান্তরযোগ্যতা** | অবাধে হস্তান্তরযোগ্য নয় | শেয়ার বাজারে অবাধে কেনাবেচা ও হস্তান্তর করা যায় |\n| **কার্য আরম্ভ** | নিবন্ধনপত্র পেলেই ব্যবসা শুরু করতে পারে | নিবন্ধনপত্র এবং কার্যারম্ভের অনুমতিপত্র উভয়ই প্রয়োজন |"
