      "id": "bus-ch4-less-3",
      "chapter_id": "bus-ch-4",
      "order_index": 3,
      "title_bn": "পাঠ ৩: সমবায় সমিতি ও রাষ্ট্রীয় ব্যবসায়",
      "content_text": "## ১. সমবায় সমিতি (Cooperative Society)\n\nপারস্পরিক অর্থনৈতিক কল্যাণ সাধনের উদ্দেশ্যে সমাজের সমমনা ও নিম্নবিত্ত বা মধ্যবিত্ত মানুষের স্বেচ্ছামূলক গণতান্ত্রিক ব্যবসায় প্রতিষ্ঠানকে **সমবায় সমিতি (Cooperative Society)** বলে। বাংলাদেশে ২০০১ সালের সমবায় আইন (সংশোধিত ২০১৩) কার্যকর রয়েছে।\n\n### সমবায়ের মৌলিক নীতি ও বৈশিষ্ট্য:\n- **একতাই বল (Unity is Strength):** পারস্পরিক সহযোগিতা ও আত্মনির্ভরশীলতা।\n- **ন্যূনতম সদস্য সংখ্যা:** প্রাথমিক সমবায় সমিতিতে সর্বনিম্ন ২০ জন প্রাপ্তবয়স্ক সদস্য প্রয়োজন।\n- **গণতান্ত্রিক ব্যবস্থাপনা:** শেয়ার সংখ্যা নির্বিশেষে প্রত্যেক সদস্যের ভোটাধিকার সমান (এক সদস্য = এক ভোট)।\n- **মুনাফা বণ্টন:** অর্জিত নীট মুনাফার কমপক্ষে ১৫% বাধ্যতামূলকভাবে সংরক্ষিত তহবিলে (Reserve Fund) এবং ৩% সমবায় উন্নয়ন তহবিলে জমা রাখতে হয়।\n\n---\n\n## ২. রাষ্ট্রীয় ব্যবসায় (State Enterprise)\n\nরাষ্ট্র কর্তৃক বা সরকারের সরাসরি মালিকানা, অর্থায়ন ও পরিচালনায় গঠিত ব্যবসায় সংগঠনকে **রাষ্ট্রীয় ব্যবসায় (State Owned Enterprise - SOE)** বলে।\n\n### উদ্দেশ্য ও গুরুত্ব:\n- **জনকল্যাণ:** মুনাফা অর্জনের চেয়ে নাগরিক সেবা ও জনকল্যাণই রাষ্ট্রীয় ব্যবসায়ের মুখ্য উদ্দেশ্য।\n- **ভারী ও কৌশলগত শিল্প:** যেসব খাতে বিপুল পুঁজির প্রয়োজন এবং লাভজনকতা অনিশ্চিত (যেমন—রেলওয়ে, বিদ্যুৎ উন্নয়ন বোর্ড, বিমান, অস্ত্রাগার), সেখানে রাষ্ট্র নিজেই ব্যবসায় গড়ে তোলে।\n- **একচেটিয়া শোষণ রোধ:** বেসরকারি ব্যবসায়ীদের অযৌক্তিক মূল্যবৃদ্ধি ও কৃত্রিম সংকট রোধ করে পণ্যের দাম স্থিতিশীল রাখা।\n- **উদাহরণ:** বাংলাদেশ রেলওয়ে, ওয়াসা (WASA), পিডিবি (BPDB), বিসিআইসি (BCIC), টিসিবি (TCB)।",
      "content": "## ১. সমবায় সমিতি (Cooperative Society)\n\nপারস্পরিক অর্থনৈতিক কল্যাণ সাধনের উদ্দেশ্যে সমাজের সমমনা ও নিম্নবিত্ত বা মধ্যবিত্ত মানুষের স্বেচ্ছামূলক গণতান্ত্রিক ব্যবসায় প্রতিষ্ঠানকে **সমবায় সমিতি (Cooperative Society)** বলে। বাংলাদেশে ২০০১ সালের সমবায় আইন (সংশোধিত ২০১৩) কার্যকর রয়েছে।\n\n### সমবায়ের মৌলিক নীতি ও বৈশিষ্ট্য:\n- **একতাই বল (Unity is Strength):** পারস্পরিক সহযোগিতা ও আত্মনির্ভরশীলতা।\n- **ন্যূনতম সদস্য সংখ্যা:** প্রাথমিক সমবায় সমিতিতে সর্বনিম্ন ২০ জন প্রাপ্তবয়স্ক সদস্য প্রয়োজন।\n- **গণতান্ত্রিক ব্যবস্থাপনা:** শেয়ার সংখ্যা নির্বিশেষে প্রত্যেক সদস্যের ভোটাধিকার সমান (এক সদস্য = এক ভোট)।\n- **মুনাফা বণ্টন:** অর্জিত নীট মুনাফার কমপক্ষে ১৫% বাধ্যতামূলকভাবে সংরক্ষিত তহবিলে (Reserve Fund) এবং ৩% সমবায় উন্নয়ন তহবিলে জমা রাখতে হয়।\n\n---\n\n## ২. রাষ্ট্রীয় ব্যবসায় (State Enterprise)\n\nরাষ্ট্র কর্তৃক বা সরকারের সরাসরি মালিকানা, অর্থায়ন ও পরিচালনায় গঠিত ব্যবসায় সংগঠনকে **রাষ্ট্রীয় ব্যবসায় (State Owned Enterprise - SOE)** বলে।\n\n### উদ্দেশ্য ও গুরুত্ব:\n- **জনকল্যাণ:** মুনাফা অর্জনের চেয়ে নাগরিক সেবা ও জনকল্যাণই রাষ্ট্রীয় ব্যবসায়ের মুখ্য উদ্দেশ্য।\n- **ভারী ও কৌশলগত শিল্প:** যেসব খাতে বিপুল পুঁজির প্রয়োজন এবং লাভজনকতা অনিশ্চিত (যেমন—রেলওয়ে, বিদ্যুৎ উন্নয়ন বোর্ড, বিমান, অস্ত্রাগার), সেখানে রাষ্ট্র নিজেই ব্যবসায় গড়ে তোলে।\n- **একচেটিয়া শোষণ রোধ:** বেসরকারি ব্যবসায়ীদের অযৌক্তিক মূল্যবৃদ্ধি ও কৃত্রিম সংকট রোধ করে পণ্যের দাম স্থিতিশীল রাখা।\n- **উদাহরণ:** বাংলাদেশ রেলওয়ে, ওয়াসা (WASA), পিডিবি (BPDB), বিসিআইসি (BCIC), টিসিবি (TCB)।"
