      "id": "bus-ch5-less-3",
      "chapter_id": "bus-ch-5",
      "order_index": 3,
      "title_bn": "পাঠ ৩: ব্যবসায়িক ঝুঁকি ও বীমা (Business Risk & Insurance)",
      "content_text": "## ১. ব্যবসায়িক ঝুঁকি ও বীমার ধারণা\n\nব্যবসায়ের প্রতিটি পদক্ষেপে সম্ভাব্য আর্থিক ক্ষতি ও অনিশ্চয়তা জড়িয়ে থাকে। আগুনে কারখানা পুড়ে যাওয়া, নৌপথে জাহাজডুবি বা সড়ক দুর্ঘটনায় পণ্য ধ্বংস হওয়া, পণ্যের মূল্যপতন ইত্যাদি বহুবিধ কারণে ব্যবসায় মারাত্মক ক্ষতির সম্মুখীন হতে পারে।\n\n> **সংজ্ঞা:** যে চুক্তি অনুযায়ী এক পক্ষ (বীমা কোম্পানি) নির্দিষ্ট প্রিমিয়ামের বিনিময়ে অন্য পক্ষের (বীমাগ্রহীতা) কোনো নির্দিষ্ট অনিশ্চিত বিপদের ফলে সৃষ্ট আর্থিক ক্ষতিপূরণ করার প্রতিশ্রুতি দেয়, তাকে **বীমা (Insurance)** বলে।\n\nবীমা কোনো দুর্ঘটনাকে রোধ করতে পারে না, কিন্তু দুর্ঘটনার ফলে সৃষ্ট আর্থিক ক্ষতির ঝুঁকি বহু মানুষের মাঝে বণ্টন করে ক্ষতিপূরণ নিশ্চিত করে।\n\n---\n\n## ২. ব্যবসায়ের ক্ষেত্রে প্রয়োজনীয় প্রধান বীমাসমূহ\n\n1. **অগ্নি বীমা (Fire Insurance):**\n   - আগুনে কারখানা, গুদাম বা দোকান পুড়ে যাওয়ার ফলে যে প্রত্যক্ষ আর্থিক ক্ষতি হয়, তা পূরণে অগ্নি বীমা করা হয়।\n2. **নৌ বীমা (Marine Insurance):**\n   - নদী বা সমুদ্রপথে পণ্য পরিবহনের সময় ঝড়, তুফান, জলদস্যুতা বা জাহাজডুবির ফলে সৃষ্ট ক্ষতিপূরণে নৌ বীমা অপরিহার্য। এটি বিশ্বের প্রাচীনতম বীমা।\n3. **দুর্ঘটনা বীমা (Accident Insurance):**\n   - কর্মকর্তা-কর্মচারীদের কাজের সময় অঙ্গহানি, দুর্ঘটনা বা মৃত্যুজনিত ক্ষতির জন্য ক্ষতিপূরণ দিতে এই বীমা করা হয়।\n4. **শস্য বীমা ও গবাদিপশু বীমা (Crop & Livestock Insurance):**\n   - বন্যা, খরা বা মহামারিতে ফসল নষ্ট হলে কিংবা ডেইরি ও পোলট্রি খামারে পশু মারা গেলে আর্থিক সুরক্ষা দিতে কৃষিজীবীদের জন্য এটি অত্যন্ত কল্যাণকর।",
      "content": "## ১. ব্যবসায়িক ঝুঁকি ও বীমার ধারণা\n\nব্যবসায়ের প্রতিটি পদক্ষেপে সম্ভাব্য আর্থিক ক্ষতি ও অনিশ্চয়তা জড়িয়ে থাকে। আগুনে কারখানা পুড়ে যাওয়া, নৌপথে জাহাজডুবি বা সড়ক দুর্ঘটনায় পণ্য ধ্বংস হওয়া, পণ্যের মূল্যপতন ইত্যাদি বহুবিধ কারণে ব্যবসায় মারাত্মক ক্ষতির সম্মুখীন হতে পারে।\n\n> **সংজ্ঞা:** যে চুক্তি অনুযায়ী এক পক্ষ (বীমা কোম্পানি) নির্দিষ্ট প্রিমিয়ামের বিনিময়ে অন্য পক্ষের (বীমাগ্রহীতা) কোনো নির্দিষ্ট অনিশ্চিত বিপদের ফলে সৃষ্ট আর্থিক ক্ষতিপূরণ করার প্রতিশ্রুতি দেয়, তাকে **বীমা (Insurance)** বলে।\n\nবীমা কোনো দুর্ঘটনাকে রোধ করতে পারে না, কিন্তু দুর্ঘটনার ফলে সৃষ্ট আর্থিক ক্ষতির ঝুঁকি বহু মানুষের মাঝে বণ্টন করে ক্ষতিপূরণ নিশ্চিত করে।\n\n---\n\n## ২. ব্যবসায়ের ক্ষেত্রে প্রয়োজনীয় প্রধান বীমাসমূহ\n\n1. **অগ্নি বীমা (Fire Insurance):**\n   - আগুনে কারখানা, গুদাম বা দোকান পুড়ে যাওয়ার ফলে যে প্রত্যক্ষ আর্থিক ক্ষতি হয়, তা পূরণে অগ্নি বীমা করা হয়।\n2. **নৌ বীমা (Marine Insurance):**\n   - নদী বা সমুদ্রপথে পণ্য পরিবহনের সময় ঝড়, তুফান, জলদস্যুতা বা জাহাজডুবির ফলে সৃষ্ট ক্ষতিপূরণে নৌ বীমা অপরিহার্য। এটি বিশ্বের প্রাচীনতম বীমা।\n3. **দুর্ঘটনা বীমা (Accident Insurance):**\n   - কর্মকর্তা-কর্মচারীদের কাজের সময় অঙ্গহানি, দুর্ঘটনা বা মৃত্যুজনিত ক্ষতির জন্য ক্ষতিপূরণ দিতে এই বীমা করা হয়।\n4. **শস্য বীমা ও গবাদিপশু বীমা (Crop & Livestock Insurance):**\n   - বন্যা, খরা বা মহামারিতে ফসল নষ্ট হলে কিংবা ডেইরি ও পোলট্রি খামারে পশু মারা গেলে আর্থিক সুরক্ষা দিতে কৃষিজীবীদের জন্য এটি অত্যন্ত কল্যাণকর।"
