      "title_bn": "পাঠ ১: বিপণনের ধারণা ও মৌলিক কার্যাবলি",
      "content_text": "## ১. বিপণন কী? (Concept of Marketing)\n\nসাধারণ ভাষায় পণ্য কেনাবেচাকে বিপণন মনে করা হলেও প্রকৃতপক্ষে বিপণনের আওতা অনেক বিস্তৃত। \n\n> **সংজ্ঞা:** পণ্য বা সেবা উৎপাদনের পূর্ব থেকে শুরু করে চূড়ান্ত ভোক্তা বা ব্যবহারকারীর নিকট সন্তোষজনকভাবে পৌঁছে দেওয়া এবং বিক্রয়োত্তর সেবা নিশ্চিত করার যাবতীয় সমন্বিত অর্থনৈতিক কর্মকাণ্ডকে **বিপণন বা বাজারজাতকরণ (Marketing)** বলে।\n\nআধুনিক বিপণনের মূল কথাই হলো **ভোক্তা সন্তুষ্টি (Customer Satisfaction)**। বর্তমান বিশ্বে বলা হয়—\"ভোক্তাই রাজা (Customer is the King)\"।\n\n---\n\n## ২. বিপণনের মৌলিক কার্যাবলিসমূহ\n\nবিপণন প্রক্রিয়ায় নিম্নলিখিত অপরিহার্য কাজগুলো অন্তর্ভুক্ত থাকে:\n\n1. **ক্রয় (Buying):** উৎপাদনের জন্য কাঁচামাল কিংবা বিক্রয়ের জন্য সঠিক পণ্য সংগ্রহ করা।\n2. **বিক্রয় (Selling):** পণ্যের মালিকানা ক্রেতার নিকট হস্তান্তর করে প্রতিষ্ঠানের জন্য অর্থ ও মুনাফা অর্জন।\n3. **পরিবহন (Transportation):** পণ্য এক স্থান থেকে অন্য স্থানে নিয়ে গিয়ে পণ্যের **স্থানগত উপযোগ** সৃষ্টি করে।\n4. **গুদামজাতকরণ (Warehousing):** উৎপাদন ও ভোগের মধ্যকার সময়ের ব্যবধান দূর করে পণ্যের **সময়গত বা কালগত উপযোগ** সৃষ্টি করে।\n5. **প্রমিতকরণ (Standardization):** পণ্যের গুণাগুণ, আকার, ওজন, রঙ ও স্বাদ বিবেচনা করে পণ্যের নির্দিষ্ট মান নির্ধারণ করা।\n6. **পর্যায়িতকরণ (Grading):** নির্ধারিত মান (Standard) অনুযায়ী পণ্যকে বিভিন্ন শ্রেণিতে বা গ্রেডে (যেমন—এ গ্রেড, বি গ্রেড) বিন্যস্ত করা।\n7. **মোড়কীকরণ (Packaging):** পণ্যকে আকর্ষণীয় করা এবং নষ্ট হওয়া বা ভেঙে যাওয়া থেকে রক্ষা করতে উপযুক্ত পাত্র বা প্যাকেটে আবৃত করা।\n8. **বাজার তথ্য সংগ্রহ ও ভোক্তা বিশ্লেষণ:** ভোক্তাদের পছন্দ, আয় ও রুচি সম্পর্কে নিয়মিত গবেষণা করা।",
      "content": "## ১. বিপণন কী? (Concept of Marketing)\n\nসাধারণ ভাষায় পণ্য কেনাবেচাকে বিপণন মনে করা হলেও প্রকৃতপক্ষে বিপণনের আওতা অনেক বিস্তৃত। \n\n> **সংজ্ঞা:** পণ্য বা সেবা উৎপাদনের পূর্ব থেকে শুরু করে চূড়ান্ত ভোক্তা বা ব্যবহারকারীর নিকট সন্তোষজনকভাবে পৌঁছে দেওয়া এবং বিক্রয়োত্তর সেবা নিশ্চিত করার যাবতীয় সমন্বিত অর্থনৈতিক কর্মকাণ্ডকে **বিপণন বা বাজারজাতকরণ (Marketing)** বলে।\n\nআধুনিক বিপণনের মূল কথাই হলো **ভোক্তা সন্তুষ্টি (Customer Satisfaction)**। বর্তমান বিশ্বে বলা হয়—\"ভোক্তাই রাজা (Customer is the King)\"।\n\n---\n\n## ২. বিপণনের মৌলিক কার্যাবলিসমূহ\n\nবিপণন প্রক্রিয়ায় নিম্নলিখিত অপরিহার্য কাজগুলো অন্তর্ভুক্ত থাকে:\n\n1. **ক্রয় (Buying):** উৎপাদনের জন্য কাঁচামাল কিংবা বিক্রয়ের জন্য সঠিক পণ্য সংগ্রহ করা।\n2. **বিক্রয় (Selling):** পণ্যের মালিকানা ক্রেতার নিকট হস্তান্তর করে প্রতিষ্ঠানের জন্য অর্থ ও মুনাফা অর্জন।\n3. **পরিবহন (Transportation):** পণ্য এক স্থান থেকে অন্য স্থানে নিয়ে গিয়ে পণ্যের **স্থানগত উপযোগ** সৃষ্টি করে।\n4. **গুদামজাতকরণ (Warehousing):** উৎপাদন ও ভোগের মধ্যকার সময়ের ব্যবধান দূর করে পণ্যের **সময়গত বা কালগত উপযোগ** সৃষ্টি করে।\n5. **প্রমিতকরণ (Standardization):** পণ্যের গুণাগুণ, আকার, ওজন, রঙ ও স্বাদ বিবেচনা করে পণ্যের নির্দিষ্ট মান নির্ধারণ করা।\n6. **পর্যায়িতকরণ (Grading):** নির্ধারিত মান (Standard) অনুযায়ী পণ্যকে বিভিন্ন শ্রেণিতে বা গ্রেডে (যেমন—এ গ্রেড, বি গ্রেড) বিন্যস্ত করা।\n7. **মোড়কীকরণ (Packaging):** পণ্যকে আকর্ষণীয় করা এবং নষ্ট হওয়া বা ভেঙে যাওয়া থেকে রক্ষা করতে উপযুক্ত পাত্র বা প্যাকেটে আবৃত করা।\n8. **বাজার তথ্য সংগ্রহ ও ভোক্তা বিশ্লেষণ:** ভোক্তাদের পছন্দ, আয় ও রুচি সম্পর্কে নিয়মিত গবেষণা করা।"
