      "order_index": 2,
      "title_bn": "পাঠ ২: বিপণন মিশ্রণ (4Ps of Marketing)",
      "content_text": "## ১. বিপণন মিশ্রণ কী? (Marketing Mix)\n\nটার্গেট বাজারের গ্রাহকদের সন্তুষ্ট করার জন্য বিপণনকারী যে সকল নিয়ন্ত্রনযোগ্য কৌশলের সংমিশ্রণ ঘটান, তাকে **বিপণন মিশ্রণ (Marketing Mix)** বলে। অধ্যাপক ই. জেরোম ম্যাকার্থি বিপণন মিশ্রণকে ৪টি 'P'-এর মাধ্যমে প্রকাশ করেছেন:\n\n$$\\text{Marketing Mix (4Ps)} = \\text{Product} + \\text{Price} + \\text{Place} + \\text{Promotion}$$\n\n---\n\n## ২. ৪টি 'P'-এর বিশদ ব্যাখ্যা\n\n1. **পণ্য (Product):**\n   - যা কিছু গ্রাহকের প্রয়োজন ও অভাব মেটাতে বাজারে উপস্থাপন করা হয়। পণ্যের নকশা, কার্যকারিতা, ব্র্যান্ড নেম, মোড়ক ও বিক্রয়োত্তর সেবা।\n2. **মূল্য (Price):**\n   - পণ্য বা সেবা ভোগ করার বিনিময়ে ক্রেতাকে যে পরিমাণ অর্থ পরিশোধ করতে হয়। মূল্য নির্ধারণে উৎপাদন খরচ, গ্রাহকের ক্রয়ক্ষমতা ও প্রতিদ্বন্দীদের দাম বিবেচনা করতে হয়।\n3. **স্থান বা বণ্টন (Place / Distribution):**\n   - উৎপাদিত পণ্য কারখানা থেকে কীভাবে এবং কোন মধ্যস্থতাকারীদের (ডিলার, পাইকার, খুচরা বিক্রেতা) মাধ্যমে ভোক্তার হাতের নাগালে পৌঁছাবে তা নিশ্চিত করা।\n4. **প্রসার বা প্রচার (Promotion):**\n   - পণ্য সম্পর্কে গ্রাহকদের অবহিত করা, আকৃষ্ট করা এবং কিনতে উৎসাহিত করার যাবতীয় যোগাযোগ মাধ্যম (বিজ্ঞাপন, ব্যক্তিগত বিক্রয়, বিক্রয় প্রসার ও জনসংযোগ)।",
      "content": "## ১. বিপণন মিশ্রণ কী? (Marketing Mix)\n\nটার্গেট বাজারের গ্রাহকদের সন্তুষ্ট করার জন্য বিপণনকারী যে সকল নিয়ন্ত্রনযোগ্য কৌশলের সংমিশ্রণ ঘটান, তাকে **বিপণন মিশ্রণ (Marketing Mix)** বলে। অধ্যাপক ই. জেরোম ম্যাকার্থি বিপণন মিশ্রণকে ৪টি 'P'-এর মাধ্যমে প্রকাশ করেছেন:\n\n$$\\text{Marketing Mix (4Ps)} = \\text{Product} + \\text{Price} + \\text{Place} + \\text{Promotion}$$\n\n---\n\n## ২. ৪টি 'P'-এর বিশদ ব্যাখ্যা\n\n1. **পণ্য (Product):**\n   - যা কিছু গ্রাহকের প্রয়োজন ও অভাব মেটাতে বাজারে উপস্থাপন করা হয়। পণ্যের নকশা, কার্যকারিতা, ব্র্যান্ড নেম, মোড়ক ও বিক্রয়োত্তর সেবা।\n2. **মূল্য (Price):**\n   - পণ্য বা সেবা ভোগ করার বিনিময়ে ক্রেতাকে যে পরিমাণ অর্থ পরিশোধ করতে হয়। মূল্য নির্ধারণে উৎপাদন খরচ, গ্রাহকের ক্রয়ক্ষমতা ও প্রতিদ্বন্দীদের দাম বিবেচনা করতে হয়।\n3. **স্থান বা বণ্টন (Place / Distribution):**\n   - উৎপাদিত পণ্য কারখানা থেকে কীভাবে এবং কোন মধ্যস্থতাকারীদের (ডিলার, পাইকার, খুচরা বিক্রেতা) মাধ্যমে ভোক্তার হাতের নাগালে পৌঁছাবে তা নিশ্চিত করা।\n4. **প্রসার বা প্রচার (Promotion):**\n   - পণ্য সম্পর্কে গ্রাহকদের অবহিত করা, আকৃষ্ট করা এবং কিনতে উৎসাহিত করার যাবতীয় যোগাযোগ মাধ্যম (বিজ্ঞাপন, ব্যক্তিগত বিক্রয়, বিক্রয় প্রসার ও জনসংযোগ)।"
