      "stem": "ডা. আফসানা এমবিবিএস পাস করে সরকারি চাকরির পেছনে না ছুটে নিজ এলাকায় একটি আধুনিক ক্লিনিক ও ডায়াগনস্টিক সেন্টার স্থাপন করেন। তিনি নির্ধারিত ভিজিটের বিনিময়ে রোগীদের চিকিৎসা দেন এবং তাঁর ক্লিনিকে রক্ত-প্রস্রাব পরীক্ষার ব্যবস্থা রয়েছে। তাঁর স্বামী ব্যারিস্টার ফাহিম একই ভবনে একটি ল ফার্ম খুলে আইনগত পরামর্শ সেবা প্রদান করেন।",
