        "kha": "সমাজের মানুষের মনোভাব, জাতিগত ঐতিহ্য, ধর্মীয় বিশ্বাস, সংস্কৃতি, শিক্ষা ও জনসংখ্যা কাঠামো যে সামগ্রিক পরিবেশ সৃষ্টি করে তাকে সামাজিক পরিবেশ বলে। সামাজিক মূল্যবোধের ওপর ভিত্তি করে পণ্যের চাহিদা নির্ধারিত হয়।",
