      "stem": "মেঘনা নদীর তীরে অবস্থিত একটি উপজেলায় পর্যাপ্ত মিঠাপানি, গ্যাস ও সস্তা শ্রমিকের প্রাচুর্য থাকায় সেখানে কয়েকটি সুতা ও টেক্সটাইল মিল গড়ে ওঠে। কিন্তু ঘনঘন রাজনৈতিক ধর্মঘট, বিদ্যুৎ বিভ্রাট এবং অনুন্নত কাঁচা রাস্তার কারণে কারখানার কাঁচামাল সময়মতো পৌঁছাতে পারত না এবং তৈরি পণ্য জাহাজে তুলতে দেরি হতো। ফলে বিদেশি ক্রেতারা ক্রয়াদেশ বাতিল করতে শুরু করে।",
