      "stem": "পাবনার ঈশ্বরদীর এক প্রত্যন্ত গ্রামে বিপুল পরিমাণ লিচু উৎপাদিত হয়। কিন্তু সংরক্ষণের অভাবে প্রতি বছর প্রচুর লিচু পচে যেত। স্থানীয় যুবক ফাহিম লিচুর রস ও জেলি তৈরির একটি প্রক্রিয়াজাতকরণ কারখানা স্থাপন করলেন। বর্তমানে তাঁর কারখানায় ৫০ জন নারী-পুরুষ কাজ করছেন এবং ঈশ্বরদীর লিচুর জুস এখন সারাদেশে সুনাম অর্জন করেছে।",
