      "stem": "একটি নামকরা জুতো প্রস্তুতকারী কোম্পানি আফ্রিকার একটি অনগ্রসর দ্বীপে নতুন বাজার অনুসন্ধানে দুজন কর্মকর্তাকে পাঠাল। প্রথম কর্মকর্তা ফিরে এসে রিপোর্ট দিলেন, 'সেখানকার কোনো মানুষই জুতো পরে না, তাই সেখানে জুতো বিক্রির কোনো সম্ভাবনাই নেই।' কিন্তু দ্বিতীয় কর্মকর্তা এসে অত্যন্ত উৎফুল্ল হয়ে রিপোর্ট দিলেন, 'সেখানকার কোনো মানুষ এখনো জুতো পরেনি, তাই পুরো দ্বীপে জুতো ব্যবহারের অভ্যাস গড়ে তুলে কোটি কোটি টাকার বিশাল বাজার দখলের অসাধারণ সুযোগ রয়েছে!'",
