      "stem": "স্নাতক শেষ করে কামাল একটি বেসরকারি প্রতিষ্ঠানে সামান্য বেতনে সকাল ৯টা থেকে রাত ৮টা পর্যন্ত ক্লার্কের চাকরি করতেন। বসের অতিরিক্ত কাজের চাপ ও স্বল্প বেতনে তিনি হতাশ হয়ে পড়েন। পরবর্তীতে তিনি চাকরি ছেড়ে যুব উন্নয়ন থেকে আধুনিক মাশরুম চাষের প্রশিক্ষণ নেন। নিজের জমানো মাত্র ২০ হাজার টাকা দিয়ে ঘরের এক কোণে মাশরুম চাষ শুরু করেন। বর্তমানে তিনি মাসে ৫০ হাজার টাকার বেশি আয় করছেন এবং নিজের কাজের সময় নিজেই নির্ধারণ করেন।",
