        "ka": "নিজের পুঁজি বা ঋণ করা স্বল্প সম্পদ, নিজস্ব জ্ঞান, বুদ্ধি ও দক্ষতাকে কাজে লাগিয়ে জীবিকা অর্জনের জন্য নিজস্ব কর্মসংস্থান সৃষ্টি করাকে আত্মকর্মসংস্থান বলে।",
        "kha": "মজুরিভিত্তিক চাকরিতে নির্দিষ্ট বেতনের বিনিময়ে অন্যের অধীনস্থ থেকে চুক্তি অনুযায়ী কাজ করতে হয় এবং স্বাধীনতা থাকে না। অন্যদিকে আত্মকর্মসংস্থানে ব্যক্তি সম্পূর্ণ স্বাধীন এবং নিজেই নিজের কাজের নিয়ন্ত্রণকারী ও মুনাফার অধিকারী।",
