      "stem": "টাঙ্গাইলের রমিজ মিয়ার পরিবার বংশপরম্পরায় বাঁশ ও বেতের ডালা, কুলা, চাটাই ও বিভিন্ন শৌখিন আসবাবপত্র তৈরি করে। পরিবারের সবাই এতে শ্রম দেয়। কিন্তু প্লাস্টিকের সস্তা পণ্যের আগ্রাসনে তাদের তৈরি পণ্যের চাহিদা কমে যায় এবং তারা অর্থাভাবে পড়ে। রমিজ মিয়ার ছেলে সুমন ইউটিউব দেখে বাঁশ ও বেত দিয়ে আধুনিক ল্যাম্পশেড, পেনহোল্ডার ও আকর্ষণীয় হোম ডেকর সামগ্রী তৈরি করে অনলাইন পেজে বিক্রি শুরু করেন। এতে তাদের আয় তিনগুণ বেড়ে যায়।",
