        "kha": "রাষ্ট্রীয় ব্যবসায় জনগণের ট্যাক্সের টাকায় পরিচালিত একটি জনকল্যাণমূলক প্রতিষ্ঠান। এর মূল উদ্দেশ্য ব্যবসায়িক লাভ করা নয়, বরং নাগরিকদের মৌলিক সুযোগ-সুবিধা নিশ্চিত করা, নিত্যপ্রয়োজনীয় পণ্যের বাজারমূল্য স্থিতিশীল রাখা এবং সর্বসাধারণের সেবা করা।",
