      "stem": "কৃষি প্রকৌশলী নাজমুল সাহেব দীর্ঘ পাঁচ বছর গবেষণার পর জ্বালানিসাশ্রয়ী ও স্বল্পমূল্যের একটি ভ্রাম্যমাণ ধান মাড়াই যন্ত্র উদ্ভাবন করেন। কিন্তু তিনি উদ্ভাবনটির সরকারি পেটেন্ট নিবন্ধন করাননি। কিছুদিন পর একটি বড় কৃষি যন্ত্রপাতি নির্মাতা কোম্পানি তাঁর ডিজাইন ও প্রযুক্তি হুবহু নকল করে বড় আকারে যন্ত্রটি তৈরি করে বাজারে ছাড়ে। নাজমুল সাহেব কোম্পানিটির বিরুদ্ধে ক্ষতিপূরণ দাবি করতে গিয়ে আইনি জটিলতায় পড়েন।",
