      "stem": "জনাব আসাদ 'তাজা বেকারি' নামে একটি মিষ্টি ও বিস্কুটের ব্র্যান্ড গড়ে তোলেন এবং তাঁর আকর্ষণীয় মোড়ক ও লোগো সরকারিভাবে ট্রেডমার্ক নিবন্ধন করান। তাঁর পণ্যের সুনাম চারিদিকে ছড়িয়ে পড়ে। কিছুদিন পর তিনি লক্ষ্য করলেন পাশের বাজারের এক অসাধু ব্যবসায়ী 'তাজা' নামের বানান সামান্য পরিবর্তন করে প্রায় একই রঙের প্যাকেটে নিম্নমানের বিস্কুট বাজারে ছাড়ছে। ফলে ক্রেতারা বিভ্রান্ত হচ্ছে এবং আসাদের বিক্রি কমে যাচ্ছে। আসাদ তাৎক্ষণিকভাবে ভোক্তা অধিকার অধিদপ্তর ও আদালতে মামলা করেন।",
