      "stem": "বন্ধুদের সাফল্যে অনুপ্রাণিত হয়ে সুমন কোনো পূর্বপরিকল্পনা ছাড়াই শহরের কেন্দ্রস্থলে একটি বিলাসবহুল ফাস্টফুডের দোকান খুলে বসেন। তিনি বাজারের ক্রেতাদের চাহিদা, নিকটবর্তী প্রতিযোগী দোকানের সংখ্যা এবং প্রতিদিনের ভাড়া ও পরিচালন খরচ হিসাব করেননি। মাত্র তিন মাসের মাথায় মূলধন শেষ হয়ে যায় এবং লোকসানের মুখে তিনি দোকানটি বন্ধ করতে বাধ্য হন।",
