        "kha": "একটি বাড়ি নির্মাণের জন্য যেমন নীল নকশা (Blue-print) প্রয়োজন, তেমনি একটি ব্যবসায় কোন পথে পরিচালিত হবে, কী পণ্য বিক্রি হবে এবং কীভাবে ঝুঁকি মোকাবিলা হবে তা ব্যবসায় পরিকল্পনা নির্দেশ করে। এটি পথভ্রষ্ট হতে দেয় না বলে একে দিকনির্দেশক দলিল বলা হয়।",
