      "stem": "বান্দরবানের রুমা ও সাজেক ভ্যালিতে স্থানীয় যুবক জন ট্রাভেলার্সদের জন্য পরিবেশবান্ধব বাঁশ ও কাঠের কটেজ নির্মাণ করেছেন এবং পাহাড়ি ঐতিহ্যবাহী স্বাস্থ্যসম্মত খাবারের রেস্তোরাঁ খুলেছেন। তিনি স্থানীয় পাহাড়ি তরুণদের গাইড হিসেবে প্রশিক্ষণ দিয়েছেন। প্রতিদিন দেশি-বিদেশি শত শত পর্যটক তাঁর রিসোর্টে অবস্থান করছেন এবং পাহাড়ি হস্তশিল্প সামগ্রী কিনছেন।",
      "ka": "বিশ্বের দীর্ঘতম প্রাকৃতিক সমুদ্র সৈকত কোথায় অবস্থিত?",
      "kha": "পর্যটন শিল্পকে 'অদৃশ্য রপ্তানি' (Invisible Export) বলা হয় কেন?",
