      "gha": "বাংলাদেশের প্রাকৃতিক সৌন্দর্যকে অর্থনৈতিক শক্তিতে রূপান্তর করতে জনের মতো উদ্যোক্তাদের ভূমিকা মূল্যায়ন করো।",
