        "kha": "বিদেশি পর্যটকরা দেশে এসে হোটেল, পরিবহন, খাবার ও বিনোদন বাবদ প্রচুর বৈদেশিক মুদ্রা খরচ করেন। এতে পণ্য দেশের বাইরে না পাঠিয়েও দেশেই বিপুল বৈদেশিক মুদ্রা অর্জিত হয়, তাই পর্যটন খাতকে 'অদৃশ্য রপ্তানি' বলা হয়।",
