      "stem": "একটি সফটওয়্যার ফার্ম নতুন মোবাইল অ্যাপ তৈরির জন্য সম্প্রতি পাঁচজন তরুণ প্রোগ্রামারকে নিয়োগ দিল। কিন্তু কাজে যোগ দেওয়ার পর দেখা গেল তারা বিশ্ববিদ্যালয় থেকে তাত্ত্বিক জ্ঞান নিয়ে এলেও আধুনিক ফ্রেমওয়ার্ক ও সাইবার নিরাপত্তার বাস্তব কাজ জানে না। ফার্মের প্রধান নির্বাহী তাঁদের কাজে বরখাস্ত না করে এক মাসের জন্য বিদেশি প্রশিক্ষকের অধীনে বিশেষ বুটক্যাম্প ও ব্যবহারিক প্রশিক্ষণের ব্যবস্থা করলেন। প্রশিক্ষণ শেষে এই পাঁচজন তরুণ মিলে মাত্র তিন মাসের মধ্যে একটি বিশ্বমানের অ্যাপ তৈরি করে কোম্পানির কোটি টাকা আয় এনে দিলেন।",
