      "stem": "একটি ইলেকট্রনিক্স শোরুমের বিক্রয়কর্মী সাজ্জাদ সবসময় হাসিমুখে ক্রেতাদের স্বাগত জানান। ক্রেতার বাজেট ও পরিবারের সদস্য সংখ্যা জেনে তিনি সঠিক ক্ষমতার ওয়াশিং মেশিন বেছে নিতে আন্তরিক পরামর্শ দেন। কোনো ক্রেতা পণ্য না কিনে চলে গেলেও তিনি বিন্দুমাত্র বিরক্ত হন না, বরং হাসিমুখে ধন্যবাদ জানান। অন্যদিকে পাশের শোরুমের বিক্রেতা তুহিন রুক্ষ মেজাজে কথা বলেন এবং দাম জানতে চাইলে বলেন, 'নিলে নেন, না নিলে বিরক্ত করবেন না।' ফলে তুহিনের দোকানে ক্রেতারা আর যেতে চায় না এবং সাজ্জাদের শোরুমে প্রতিদিন ভিড় লেগেই থাকে।",
