        "gha": "সিএসআর কোনো অপব্যয় নয়, এটি ব্যবসায়ের সবচেয়ে বড় কৌশলগত বিনিয়োগ:\n\n১. অগাধ জনবিশ্বাস ও সুনাম: মানুষ যখন দেখে ব্যাংকটি শুধু মুনাফা লুটে না, মানুষের কল্যাণে ব্যয় করে, তখন সবাই নিজের কষ্টার্জিত টাকা সেই ব্যাংকেই জমা রাখতে পছন্দ করে।\n২. প্রতিযোগী সুবিধা: অন্যান্য ব্যাংকের চেয়ে এর গ্রাহকভিত্তি ও আমানত বহুগুণ বেড়ে যায়।\n৩. ব্র্যান্ড ভ্যালু: বিজ্ঞাপনে কোটি টাকা খরচ করে যে সুনাম মেলে না, একটি মানবিক সিএসআর উদ্যোগে তার চেয়ে শতগুণ বেশি আন্তরিক ব্র্যান্ড ইমেজ তৈরি হয়।\n\nঅতএব, সমাজের প্রতি দায়িত্ব পালনই প্রকারান্তরে প্রতিষ্ঠানের স্থায়ী সমৃদ্ধি ও সর্বোচ্চ মুনাফার সোপান।"
