      "stem": "লন্ডনে একটি বহুজাতিক তেল কোম্পানির শীর্ষ নির্বাহী হিসেবে বিলাসবহুল জীবনযাপন করতেন তরুণ ফজলে হাসান আবেদ। কিন্তু ১৯৭১ সালে বাংলাদেশের মুক্তিযুদ্ধ শুরু হলে তিনি আরাম-আয়েশ ত্যাগ করে স্বাধীনতাসংগ্রামে যুক্ত হন। যুদ্ধ শেষে ধ্বংসস্তূপে গৃহহীন কোটি শরণার্থীদের পুনর্বাসনে নিজের লন্ডনের ফ্ল্যাট বিক্রি করে সুনামগঞ্জের প্রত্যন্ত শাল্লায় ছুটে আসেন। তিনি বুঝতে পেরেছিলেন শুধু ত্রাণের ওপর নির্ভর করে দরিদ্র মানুষ চিরকাল বাঁচে না; তাদের স্বাবলম্বী হওয়ার সক্ষমতা তৈরি করতে হবে। তিনি গড়ে তুললেন 'ব্র্যাক' এবং গ্রামীণ নারীদের জন্য বিখ্যাত লোকজ ব্র্যান্ড 'আড়ং'।",
