        "ga": "স্যার ফজলে হাসান আবেদের মধ্যে কাজ করেছিল 'উচ্চতর দেশপ্রেম, গভীর মানবতাবোধ ও সামাজিক ব্যবসায় চেতনা'।\n\nতিনি বিলাসী কর্পোরেট ক্যারিয়ার ছেড়ে দেশের চরম সংকটে নিঃস্বার্থভাবে ঝাঁপিয়ে পড়েছিলেন। তিনি সমস্যাকে কেবল দুঃখ হিসেবে দেখেননি, বরং উদ্ভাবনী উদ্যোগের মাধ্যমে স্থায়ী সমাধানের পথ খুঁজেছেন। তাঁর এই আত্মত্যাগই পরবর্তীতে বিশ্বের সর্ববৃহৎ বেসরকারি উন্নয়ন সংস্থা ব্র্যাকের জন্ম দেয়।",
